  ('15156d4c-eb20-5aea-b061-d394f1ae6d0f','annual','annual','en','vi','/ˈænjuəl/','B2','adjective','hàng năm, năm một, từng năm','/audio/vocab/annual.mp3','[{"source_text":"Our annual festival starts next Friday.","target_text":"Lễ hội thường niên của chúng ta bắt đầu thứ Sáu tới.","audio_url":"/audio/vocab/annual-ex.mp3"}]'::jsonb,'published'),
  ('58992f2e-0de2-516e-a72a-0b1577c58096','annually','annually','en','vi','/ˈænjuəli/','B2','adverb','hàng năm, năm một','/audio/vocab/annually.mp3','[{"source_text":"The company reviews salaries annually.","target_text":"Công ty xét duyệt lương hàng năm.","audio_url":"/audio/vocab/annually-ex.mp3"}]'::jsonb,'published'),
