  ('37f05cbf-392a-5a93-bb68-a90770858ecc','approve','approve','en','vi','/əˈpruːv/','B2','verb','tán thành, đồng ý, bằng lòng, chấp thuận','/audio/vocab/approve.mp3','[{"source_text":"I approve.","target_text":"Tôi chấp thuận.","audio_url":"/audio/vocab/approve-ex.mp3"}]'::jsonb,'published'),
