  ('7324a3aa-b3d6-5828-ab5d-a4ad1ffa8507','armed','armed','en','vi','/ɑːrmd/','B2','adjective','vũ trang','/audio/vocab/armed.mp3','[{"source_text":"The armed forces occupied the entire territory.","target_text":"Lực lượng vũ trang đã thâu tóm toàn bộ lãnh thổ.","audio_url":"/audio/vocab/armed-ex.mp3"}]'::jsonb,'published'),
  ('bfc108c8-16f3-5611-9e4f-be17c4a04d2c','arms','arms','en','vi','/ɑːrmz/','B2','noun','khí giới','/audio/vocab/arms.mp3','[{"source_text":"He has very strong arms.","target_text":"Anh ấy có cánh tay rất khỏe.","audio_url":"/audio/vocab/arms-ex.mp3"}]'::jsonb,'published'),
  ('a9e9c8b6-33e5-59bf-91db-5f84c48118d4','arrow','arrow','en','vi','/ˈærəʊ/','B2','noun','tên, mũi tên','/audio/vocab/arrow.mp3','[{"source_text":"Time flies like an arrow.","target_text":"Thời gian trôi nhanh như tên bắn.","audio_url":"/audio/vocab/arrow-ex.mp3"}]'::jsonb,'published'),
