  ('5c663bc2-2de3-5950-b9d9-1ede1d637ee8','automatically','automatically','en','vi','/ˌɔːtəˈmætɪkli/','B2','adverb','tự động','/audio/vocab/automatically.mp3','[{"source_text":"It happened automatically.","target_text":"Nó đã tự động xảy ra.","audio_url":"/audio/vocab/automatically-ex.mp3"}]'::jsonb,'published'),
