  ('ded59083-a602-5f27-8829-0af9b1e93944','constant','constant','en','vi','/ˈkɑːnstənt/','B2','adjective','bền lòng, kiên trì','/audio/vocab/constant.mp3','[{"source_text":"The baby''s crying was constant all night.","target_text":"Em bé khóc không ngừng suốt đêm.","audio_url":"/audio/vocab/constant-ex.mp3"}]'::jsonb,'published'),
