  ('18ec52d9-eaab-50eb-a666-c4afaafd8cb1','oxygen','oxygen','en','vi','/ˈɑːksɪdʒən/','B2','noun','Oxy','/audio/vocab/oxygen.mp3','[{"source_text":"Plants release oxygen into the air.","target_text":"Cây xanh thải oxy vào không khí.","audio_url":"/audio/vocab/oxygen-ex.mp3"}]'::jsonb,'published'),
  ('726fff44-2870-5988-8484-9576ed9aefc0','pace','pace','en','vi','/peɪs/','B2','noun','bước chân, bước','/audio/vocab/pace.mp3','[{"source_text":"Why don''t we drive out to the country for a change of pace?","target_text":"Sao chúng ta không lái xe đến vùng nông thôn để thay đổi không khí một chút nhỉ?","audio_url":"/audio/vocab/pace-ex.mp3"}]'::jsonb,'published'),
  ('2f02b0ad-4827-54da-bbcc-ee55e99beb07','packet','packet','en','vi','/ˈpækɪt/','B2','noun','gói nhỏ','/audio/vocab/packet.mp3','[{"source_text":"He bought a packet of biscuits.","target_text":"Anh ấy mua một gói bánh quy.","audio_url":"/audio/vocab/packet-ex.mp3"}]'::jsonb,'published'),
  ('1e0b9d3d-595e-500e-86ed-72fb81149954','palm','palm','en','vi','/pɑːm/','B2','noun','cây cọ, cây họ cau dừa','/audio/vocab/palm.mp3','[{"source_text":"Tall palm trees lined the beach.","target_text":"Những cây cọ cao mọc dọc bãi biển.","audio_url":"/audio/vocab/palm-ex.mp3"}]'::jsonb,'published'),
  ('7037b268-f2cd-5464-a3dd-3381cf8b4dae','panel','panel','en','vi','/ˈpænl/','B2','noun','cán ô , panô','/audio/vocab/panel.mp3','[{"source_text":"A panel of experts discussed climate change.","target_text":"Một hội đồng chuyên gia thảo luận về biến đổi khí hậu.","audio_url":"/audio/vocab/panel-ex.mp3"}]'::jsonb,'published'),
  ('799744bc-8d4b-5421-a574-18f53455fabd','panic','panic','en','vi','/ˈpænɪk/','B2','noun','cây tắc','/audio/vocab/panic.mp3','[{"source_text":"The police appealed to the crowd not to panic.","target_text":"Cảnh sát kêu gọi đám đông đừng hoảng hốt.","audio_url":"/audio/vocab/panic-ex.mp3"}]'::jsonb,'published'),
  ('55b91779-8bb2-5e9a-9e7a-1bac86f3d309','parade','parade','en','vi','/pəˈreɪd/','B2','noun','sự phô trương','/audio/vocab/parade.mp3','[{"source_text":"What a nice military parade!","target_text":"Buổi diễu binh đẹp thế!","audio_url":"/audio/vocab/parade-ex.mp3"}]'::jsonb,'published'),
  ('8a68792f-d7ed-5ecb-8ca9-1c0f6b4825ab','parallel','parallel','en','vi','/ˈpærəlel/','B2','adjective','song song','/audio/vocab/parallel.mp3','[{"source_text":"The news is from a parallel universe.","target_text":"Tin tức đến từ một vũ trụ song song.","audio_url":"/audio/vocab/parallel-ex.mp3"}]'::jsonb,'published'),
  ('432b5654-05fc-53a5-9f07-ffe0c1f8d353','parliament','parliament','en','vi','/ˈpɑːrləmənt/','B2','noun','nghị viện','/audio/vocab/parliament.mp3','[{"source_text":"He was elected to Parliament in 1970.","target_text":"Ông ấy đã được bầu vào Quốc hội vào năm 1970.","audio_url":"/audio/vocab/parliament-ex.mp3"}]'::jsonb,'published'),
  ('7a5d3efb-c4f9-5171-95b8-8fc3a5f7b3fd','part-time','part-time','en','vi','/ˌpɑːrt ˈtaɪm/','B2','phrase','không trọn ngày công','/audio/vocab/part-time.mp3','[{"source_text":"She works part-time at a small café.","target_text":"Cô ấy làm việc bán thời gian ở một quán cà phê nhỏ.","audio_url":"/audio/vocab/part-time-ex.mp3"}]'::jsonb,'published'),
  ('aaadf3fd-25f1-589c-9b69-df40f4aed10a','participant','participant','en','vi','/pɑːrˈtɪsɪpənt/','B2','noun','người tham gia, người tham dự','/audio/vocab/participant.mp3','[{"source_text":"Each participant received a small gift.","target_text":"Mỗi người tham gia nhận được một món quà nhỏ.","audio_url":"/audio/vocab/participant-ex.mp3"}]'::jsonb,'published'),
