  ('58775277-d135-5e9f-848b-8bcdb814a413','plain','plain','en','vi','/pleɪn/','B2','adjective','đồng bằng','/audio/vocab/plain.mp3','[{"source_text":"She wore a plain white dress.","target_text":"Cô ấy mặc một chiếc váy trắng đơn giản.","audio_url":"/audio/vocab/plain-ex.mp3"}]'::jsonb,'published'),
