  ('ec78e10f-dec6-551f-b079-b25a766addb4','pointed','pointed','en','vi','/ˈpɔɪntɪd/','B2','adjective','nhọn, có đầu nhọn','/audio/vocab/pointed.mp3','[{"source_text":"Tom pointed out a few mistakes I had made.","target_text":"Tom đã chỉ ra vài chỗ sai của tôi.","audio_url":"/audio/vocab/pointed-ex.mp3"}]'::jsonb,'published'),
  ('f1eb4c9d-b05c-5e6b-80e0-e78eba403a92','popularity','popularity','en','vi','/ˌpɑːpjuˈlærəti/','B2','noun','tính đại chúng','/audio/vocab/popularity.mp3','[{"source_text":"The show''s popularity keeps growing every week.","target_text":"Độ nổi tiếng của chương trình tăng lên mỗi tuần.","audio_url":"/audio/vocab/popularity-ex.mp3"}]'::jsonb,'published'),
  ('3e073a3e-3184-580e-9640-ae9ca4b53fd7','portion','portion','en','vi','/ˈpɔːrʃn/','B2','noun','phần, phần chia','/audio/vocab/portion.mp3','[{"source_text":"She ate only a small portion of rice.","target_text":"Cô ấy chỉ ăn một phần cơm nhỏ.","audio_url":"/audio/vocab/portion-ex.mp3"}]'::jsonb,'published'),
  ('d52467a7-5c19-50b1-9fa7-e7f0c5e7b181','pose','pose','en','vi','/pəʊz/','B2','verb','tư thế , kiểu','/audio/vocab/pose.mp3','[{"source_text":"Smoking poses a serious risk to health.","target_text":"Hút thuốc gây nguy cơ nghiêm trọng cho sức khỏe.","audio_url":"/audio/vocab/pose-ex.mp3"}]'::jsonb,'published'),
  ('770ab934-a731-514c-8dcb-f92af5e3dee7','possess','possess','en','vi','/pəˈzes/','B2','verb','có, chiếm hữu','/audio/vocab/possess.mp3','[{"source_text":"I only possess a small piece of land in the village.","target_text":"Tôi chỉ sở hữu một mảnh đất nhỏ trong làng.","audio_url":"/audio/vocab/possess-ex.mp3"}]'::jsonb,'published'),
  ('fc824f9b-ddaa-5f31-a74e-d51c23a2a72e','potential','potential','en','vi','/pəˈtenʃl/','B2','adjective','tiềm tàng','/audio/vocab/potential.mp3','[{"source_text":"Benedito''s work has the potential to advance the field of artificial intelligence.","target_text":"Công trình của Benedito có tiềm năng thúc đẩy lĩnh vực trí tuệ nhân tạo.","audio_url":"/audio/vocab/potential-ex.mp3"}]'::jsonb,'published'),
  ('c6106e9b-60a8-54f2-a67c-86a2ccd857d7','potentially','potentially','en','vi','/pəˈtenʃəli/','B2','adverb','tiềm năng, tiềm tàng','/audio/vocab/potentially.mp3','[{"source_text":"This medicine is potentially dangerous for children.","target_text":"Loại thuốc này có thể nguy hiểm cho trẻ em.","audio_url":"/audio/vocab/potentially-ex.mp3"}]'::jsonb,'published'),
