  ('efc88fe9-ce5d-5c60-88de-491bd16dca52','tenant','tenant','en','vi','/ˈtenənt/','C1','noun','người thuê mướn','/audio/vocab/tenant.mp3','[{"source_text":"The tenant pays rent on the first.","target_text":"Người thuê trả tiền nhà vào ngày mùng một.","audio_url":"/audio/vocab/tenant-ex.mp3"}]'::jsonb,'published'),
  ('2ad6636c-ec34-5256-859f-36076071105e','tender','tender','en','vi','/ˈtendər/','C1','adjective','mềm','/audio/vocab/tender.mp3','[{"source_text":"The steak was juicy and tender.","target_text":"Miếng bít tết mọng nước và mềm.","audio_url":"/audio/vocab/tender-ex.mp3"}]'::jsonb,'published'),
