  ('5f02dc1f-9705-5035-8e26-c92c505504ae','terminal','terminal','en','vi','/ˈtɜːrmɪnl/','C1','adjective','cuối, chót, tận cùng','/audio/vocab/terminal.mp3','[{"source_text":"Doctors diagnosed her with a terminal illness.","target_text":"Bác sĩ chẩn đoán cô mắc bệnh hiểm nghèo giai đoạn cuối.","audio_url":"/audio/vocab/terminal-ex.mp3"}]'::jsonb,'published'),
  ('b72c1ecd-4248-5a53-8fa4-845110ef9032','terminate','terminate','en','vi','/ˈtɜːrmɪneɪt/','C1','verb','vạch giới hạn, định giới hạn','/audio/vocab/terminate.mp3','[{"source_text":"She decided to terminate her pregnancy.","target_text":"Cô ấy quyết định phá thai.","audio_url":"/audio/vocab/terminate-ex.mp3"}]'::jsonb,'published')
