  ('6ec715a8-915f-5239-8d75-330b1e346208','circumnavigation','circumnavigation','en','vi','/,sə:kəm,nævi''geiʃn/','C2','noun','sự đi vòng quanh bằng đường biển','/audio/vocab/circumnavigation.mp3','[{"source_text":"The voyage was the first circumnavigation of Antarctica.","target_text":"Chuyến hải trình là vòng đi quanh Nam Cực đầu tiên.","audio_url":"/audio/vocab/circumnavigation-ex.mp3"}]'::jsonb,'published'),
  ('b45ac6ba-d6f7-5f4e-8da0-dc10b5497d2b','cocoon','cocoon','en','vi','/kə''ku:n/','C2','verb','làm kén','/audio/vocab/cocoon.mp3','[{"source_text":"She cocooned herself in blankets all winter.","target_text":"Cô ấy quấn mình trong chăn suốt mùa đông.","audio_url":"/audio/vocab/cocoon-ex.mp3"}]'::jsonb,'published'),
  ('c3539828-79c5-5476-8fcc-111034971272','commensurate','commensurate','en','vi','/kə''menʃərit/','C2','adjective','cùng diện tích với','/audio/vocab/commensurate.mp3','[{"source_text":"The reward was commensurate with her effort.","target_text":"Phần thưởng xứng đáng với công sức của cô ấy.","audio_url":"/audio/vocab/commensurate-ex.mp3"}]'::jsonb,'published'),
  ('57662af1-0b55-524e-b8f3-690f92b6512f','commensurately','commensurately','en','vi',NULL,'C2','adverb','một cách tương xứng','/audio/vocab/commensurately.mp3','[{"source_text":"He was commensurately rewarded for his efforts.","target_text":"Anh ấy được thưởng xứng đáng với công sức bỏ ra.","audio_url":"/audio/vocab/commensurately-ex.mp3"}]'::jsonb,'published'),
  ('dd816832-8852-5ad6-ba2c-97b6dcd48889','concurrence','concurrence','en','vi','/kən''kʌrəns/','C2','noun','sự trùng nhau, sự xảy ra đồng thời','/audio/vocab/concurrence.mp3','[{"source_text":"The plan won approval by general concurrence.","target_text":"Kế hoạch được thông qua nhờ sự đồng thuận chung.","audio_url":"/audio/vocab/concurrence-ex.mp3"}]'::jsonb,'published'),
  ('1f7e5aa7-1d67-5f71-8604-c420070d7de6','conjecture','conjecture','en','vi','/kən''dʤektʃə/','C2','verb','sự phỏng đoán, sự ước đoán','/audio/vocab/conjecture.mp3','[{"source_text":"They conjectured about the cause of the fire.","target_text":"Họ phỏng đoán về nguyên nhân vụ cháy.","audio_url":"/audio/vocab/conjecture-ex.mp3"}]'::jsonb,'published'),
  ('5092e8db-b001-544c-ae8a-7e4fb7a1f94c','constrained','constrained','en','vi','/kən''streind/','C2','adjective','ngượng nghịu, bối rối, không tự nhiên','/audio/vocab/constrained.mp3','[{"source_text":"He felt constrained at the formal dinner.","target_text":"Anh ấy thấy gò bó trong bữa tiệc trang trọng.","audio_url":"/audio/vocab/constrained-ex.mp3"}]'::jsonb,'published'),
  ('0ac3ee4a-0fa8-5ebc-95bc-6a2b68ea1e9c','contextual','contextual','en','vi','/kɔn''tekstjuəl/','C2','adjective','văn cảnh, ngữ cảnh, mạch văn','/audio/vocab/contextual.mp3','[{"source_text":"Meaning shifts with contextual clues in conversation.","target_text":"Nghĩa của từ thay đổi theo manh mối ngữ cảnh trong hội thoại.","audio_url":"/audio/vocab/contextual-ex.mp3"}]'::jsonb,'published'),
  ('1e9f92ef-e41a-5696-8dc1-e5ae6b938c65','contextually','contextually','en','vi',NULL,'C2','adverb','theo ngữ cảnh','/audio/vocab/contextually.mp3','[{"source_text":"The poem reads differently when understood contextually.","target_text":"Bài thơ được hiểu khác đi khi xét theo ngữ cảnh.","audio_url":"/audio/vocab/contextually-ex.mp3"}]'::jsonb,'published'),
  ('212dfd9c-5b4b-5921-ba36-66326c46948c','contractual','contractual','en','vi','/kən''træktjuəl/','C2','adjective','bằng hợp đồng, bằng giao kèo, bằng khế ước','/audio/vocab/contractual.mp3','[{"source_text":"The workers demanded their contractual rights be honored.","target_text":"Người lao động yêu cầu tôn trọng các quyền theo hợp đồng.","audio_url":"/audio/vocab/contractual-ex.mp3"}]'::jsonb,'published'),
  ('70e31316-3fd9-5bc3-b60d-1c08a8c989cc','contractually','contractually','en','vi',NULL,'C2','adverb','theo hợp đồng','/audio/vocab/contractually.mp3','[{"source_text":"We are contractually bound to finish by June.","target_text":"Theo hợp đồng, chúng tôi phải hoàn thành trước tháng Sáu.","audio_url":"/audio/vocab/contractually-ex.mp3"}]'::jsonb,'published'),
  ('c0f6ba95-dea2-5a92-b910-9ccc811f8f4a','corpse','corpse','en','vi','/kɔ:ps/','C2','noun','xác chết, thi hài','/audio/vocab/corpse.mp3','[{"source_text":"The corpse didn''t show any wounds.","target_text":"Cái xác không có bất kỳ vết thương nào.","audio_url":"/audio/vocab/corpse-ex.mp3"}]'::jsonb,'published'),
  ('140c6300-e391-5f76-a17a-2ecf04823ca2','daunt','daunt','en','vi','/dɔ:nt/','C2','verb','đe doạ, doạ nạt, doạ dẫm','/audio/vocab/daunt.mp3','[{"source_text":"","target_text":"","audio_url":null}]'::jsonb,'published'),
  ('e53b2865-3cfd-5d80-8f31-0ddb9d1d717c','daunting','daunting','en','vi',NULL,'C2','adjective','làm thoái chí, làm nản chí','/audio/vocab/daunting.mp3','[{"source_text":"The prospect of surgery was daunting for her.","target_text":"Triển vọng phải phẫu thuật khiến cô ấy nản lòng.","audio_url":"/audio/vocab/daunting-ex.mp3"}]'::jsonb,'published'),
  ('e008c4a4-e4f2-52a1-a869-2d5a4c89ef3a','deficient','deficient','en','vi','/di''fiʃənt/','C2','adjective','thiếu, thiếu hụt, không đầy đủ, không hoàn toàn','/audio/vocab/deficient.mp3','[{"source_text":"The soil was deficient in nitrogen.","target_text":"Đất bị thiếu nitơ.","audio_url":"/audio/vocab/deficient-ex.mp3"}]'::jsonb,'published'),
  ('3d6f62b3-dd6e-51ea-8c07-3d3a1e1ad15f','deficiently','deficiently','en','vi',NULL,'C2','adverb','một cách thiếu hụt, khiếm khuyết','/audio/vocab/deficiently.mp3','[{"source_text":"He answered the questions deficiently and missed the point.","target_text":"Anh ấy trả lời thiếu sót và lạc đề.","audio_url":"/audio/vocab/deficiently-ex.mp3"}]'::jsonb,'published'),
  ('3a78b851-dd0c-5ed8-8998-6aea570045af','delicatessen','delicatessen','en','vi','/,delikə''tesn/','C2','noun','món ăn ngon','/audio/vocab/delicatessen.mp3','[{"source_text":"She bought cheese at the delicatessen downtown.","target_text":"Cô ấy mua phô mai ở cửa hàng thực phẩm trong trung tâm.","audio_url":"/audio/vocab/delicatessen-ex.mp3"}]'::jsonb,'published'),
  ('78f89e42-9351-5d91-b725-1bc88559a220','denunciation','denunciation','en','vi','/di,nʌnsi''eiʃn/','C2','noun','sự tố cáo, sự tố giác, sự vạch mặt','/audio/vocab/denunciation.mp3','[{"source_text":"The mayor issued a denunciation of the violence.","target_text":"Thị trưởng đã công khai lên án vụ bạo lực.","audio_url":"/audio/vocab/denunciation-ex.mp3"}]'::jsonb,'published'),
  ('15f941a7-27d4-58bf-94b3-40217693cebb','deprivation','deprivation','en','vi','/,depri''veiʃn/','C2','noun','sự mất','/audio/vocab/deprivation.mp3','[{"source_text":"Sleep deprivation made him irritable and unfocused.","target_text":"Thiếu ngủ khiến anh ấy cáu gắt và mất tập trung.","audio_url":"/audio/vocab/deprivation-ex.mp3"}]'::jsonb,'published'),
  ('efa26a09-3e97-5273-9cf2-89c0f6ffd875','derelict','derelict','en','vi','/''derilikt/','C2','adjective','bị bỏ rơi, không ai nhìn nhận, vô chủ','/audio/vocab/derelict.mp3','[{"source_text":"The derelict factory stood empty for years.","target_text":"Nhà máy bỏ hoang trống rỗng suốt nhiều năm.","audio_url":"/audio/vocab/derelict-ex.mp3"}]'::jsonb,'published'),
  ('82203721-e568-5aff-8074-3259eb050cf2','diffuse','diffuse','en','vi','/di''fju:s/','C2','adjective','khuếch tán','/audio/vocab/diffuse.mp3','[{"source_text":"Her argument was diffuse and hard to follow.","target_text":"Lập luận của cô ấy lan man, khó theo dõi.","audio_url":"/audio/vocab/diffuse-ex.mp3"}]'::jsonb,'published'),
  ('bb9d8293-49f3-5b17-ac79-7359f5daf825','disdainful','disdainful','en','vi','/dis''deinful/','C2','adjective','có thái độ khinh thị','/audio/vocab/disdainful.mp3','[{"source_text":"He cast a disdainful glance at the mess.","target_text":"Anh ấy liếc nhìn đống bừa bộn đầy khinh bỉ.","audio_url":"/audio/vocab/disdainful-ex.mp3"}]'::jsonb,'published'),
  ('8e7e7c38-9755-57a1-8f87-62f186d53941','dispersal','dispersal','en','vi','/dis''pə:səl/','C2','noun','sự giải tán, sự phân tán','/audio/vocab/dispersal.mp3','[{"source_text":"The dispersal of the crowd took an hour.","target_text":"Việc giải tán đám đông mất một giờ.","audio_url":"/audio/vocab/dispersal-ex.mp3"}]'::jsonb,'published'),
  ('32428c07-f616-5364-b845-42ed2848ead8','disperse','disperse','en','vi','/dis''pə:s/','C2','verb','giải tán, phân tán','/audio/vocab/disperse.mp3','[{"source_text":"The police dispersed the angry crowd quickly.","target_text":"Cảnh sát nhanh chóng giải tán đám đông giận dữ.","audio_url":"/audio/vocab/disperse-ex.mp3"}]'::jsonb,'published'),
  ('1730fbfb-5bb8-55cf-97ee-fab39258def6','distill','distill','en','vi','/dis''til/','C2','verb','chảy nhỏ giọt','/audio/vocab/distill.mp3','[{"source_text":"She distilled years of research into one chapter.","target_text":"Cô ấy chắt lọc nhiều năm nghiên cứu vào một chương.","audio_url":"/audio/vocab/distill-ex.mp3"}]'::jsonb,'published'),
  ('c3b878cd-35af-5517-a945-f0e67a5fda7d','distillation','distillation','en','vi','/,disti''leiʃn/','C2','noun','sự cất','/audio/vocab/distillation.mp3','[{"source_text":"Distillation purifies the contaminated water supply.","target_text":"Chưng cất làm sạch nguồn nước bị ô nhiễm.","audio_url":"/audio/vocab/distillation-ex.mp3"}]'::jsonb,'published'),
  ('4285cd73-2e1b-5f4e-96fd-9def632dbffe','domesticity','domesticity','en','vi','/,doumes''tisiti/','C2','noun','trạng thái thuần hoá','/audio/vocab/domesticity.mp3','[{"source_text":"After years of travel, she embraced quiet domesticity.","target_text":"Sau nhiều năm phiêu bạt, cô tận hưởng cuộc sống gia đình bình yên.","audio_url":"/audio/vocab/domesticity-ex.mp3"}]'::jsonb,'published'),
  ('5745b423-ad34-5d26-b675-cb0d192b5083','eccentricity','eccentricity','en','vi','/,eksen''trisiti/','C2','noun','tính lập dị, tính kỳ cục','/audio/vocab/eccentricity.mp3','[{"source_text":"His eccentricity charmed everyone at the office.","target_text":"Tính lập dị của ông khiến mọi người ở văn phòng quý mến.","audio_url":"/audio/vocab/eccentricity-ex.mp3"}]'::jsonb,'published'),
  ('ff97124e-ed85-5c1d-8ddc-050d2ea2f824','egalitarian','egalitarian','en','vi','/i,gæli''teəriən/','C2','adjective','người theo chủ nghĩa quân bình','/audio/vocab/egalitarian.mp3','[{"source_text":"They believe in an egalitarian distribution of wealth.","target_text":"Họ tin vào việc phân phối của cải công bằng.","audio_url":"/audio/vocab/egalitarian-ex.mp3"}]'::jsonb,'published'),
  ('3bf0e332-e025-5c6d-a052-8d847f6a2430','encumber','encumber','en','vi','/in''kʌmbə/','C2','verb','làm lúng túng, làm trở ngại, làm vướng víu','/audio/vocab/encumber.mp3','[{"source_text":"Heavy debts encumbered the young company.","target_text":"Nợ nần chồng chất đè nặng lên công ty trẻ.","audio_url":"/audio/vocab/encumber-ex.mp3"}]'::jsonb,'published'),
  ('780eaa0e-881a-5f6b-84d0-adfa68520894','encumbrance','encumbrance','en','vi','/in''kʌmbrəns/','C2','noun','gánh nặng','/audio/vocab/encumbrance.mp3','[{"source_text":"The mortgage was an encumbrance on their finances.","target_text":"Khoản thế chấp là gánh nặng cho tài chính của họ.","audio_url":"/audio/vocab/encumbrance-ex.mp3"}]'::jsonb,'published'),
  ('47a923ea-dc1e-5e09-9a31-1d964c199ef8','enthuse','enthuse','en','vi','/in''θju:z/','C2','verb','tỏ ra hăng hái, đầy nhiệt tình','/audio/vocab/enthuse.mp3','[{"source_text":"The teacher enthused about her students'' progress.","target_text":"Cô giáo hào hứng khen ngợi sự tiến bộ của học trò.","audio_url":"/audio/vocab/enthuse-ex.mp3"}]'::jsonb,'published'),
  ('0a7cbe8c-4aa6-58a0-b448-f360565b8434','envisage','envisage','en','vi','/in''vizidʤ/','C2','verb','nhìn thẳng vào mặt','/audio/vocab/envisage.mp3','[{"source_text":"We envisage a future without traffic jams.","target_text":"Chúng tôi hình dung một tương lai không còn tắc đường.","audio_url":"/audio/vocab/envisage-ex.mp3"}]'::jsonb,'published'),
  ('e659c209-2b06-59c6-ada1-198cdfd6487a','equable','equable','en','vi','/''ekwəbl/','C2','adjective','không thay đổi, đều','/audio/vocab/equable.mp3','[{"source_text":"Her equable temper never wavered under pressure.","target_text":"Tính khí điềm đạm của cô không hề lay chuyển dưới áp lực.","audio_url":"/audio/vocab/equable-ex.mp3"}]'::jsonb,'published'),
  ('5a30e1a4-d6a5-57a1-8033-7f593d8071b9','extant','extant','en','vi','/eks''tænt/','C2','adjective','hiện có, hiện còn','/audio/vocab/extant.mp3','[{"source_text":"Only three extant copies remain worldwide.","target_text":"Chỉ còn ba bản còn tồn tại trên toàn thế giới.","audio_url":"/audio/vocab/extant-ex.mp3"}]'::jsonb,'published'),
  ('b8455d12-931e-5b38-9466-ed7f4da93ed1','exude','exude','en','vi','/ig''zju:d/','C2','verb','rỉ, ứa','/audio/vocab/exude.mp3','[{"source_text":"The garden exuded the scent of jasmine.","target_text":"Khu vườn tỏa ra hương hoa nhài.","audio_url":"/audio/vocab/exude-ex.mp3"}]'::jsonb,'published'),
  ('6b58ed5e-9577-5a39-8bc7-7ea6f79078fe','facsimile','facsimile','en','vi','/fæk''simili/','C2','noun','bản sao, bản chép','/audio/vocab/facsimile.mp3','[{"source_text":"The museum displayed a facsimile of the manuscript.","target_text":"Bảo tàng trưng bày một bản sao của bản thảo.","audio_url":"/audio/vocab/facsimile-ex.mp3"}]'::jsonb,'published'),
  ('f0918d61-fe0f-585b-93b3-9cd683ab4ece','ferocity','ferocity','en','vi','/fə''rouʃəsnis/','C2','noun','tính dữ tợn, tính hung ác','/audio/vocab/ferocity.mp3','[{"source_text":"The storm struck with unexpected ferocity.","target_text":"Cơn bão ập đến với sự dữ dội bất ngờ.","audio_url":"/audio/vocab/ferocity-ex.mp3"}]'::jsonb,'published'),
  ('74c7f60d-d532-5eac-8951-49b97332f18a','forfeiture','forfeiture','en','vi','/''fɔ:fitʃə/','C2','noun','sự mất','/audio/vocab/forfeiture.mp3','[{"source_text":"Gambling led to the forfeiture of their savings.","target_text":"Cờ bạc khiến họ mất trắng tiền tiết kiệm.","audio_url":"/audio/vocab/forfeiture-ex.mp3"}]'::jsonb,'published'),
  ('eb57d5df-cb0a-5a44-a783-d0e45607675a','gale','gale','en','vi','/geil/','C2','noun','cơn gió mạnh','/audio/vocab/gale.mp3','[{"source_text":"The gale tore tiles from the roof.","target_text":"Cơn gió mạnh giật tung ngói khỏi mái nhà.","audio_url":"/audio/vocab/gale-ex.mp3"}]'::jsonb,'published'),
  ('3423c4cc-0276-5a6c-9657-29797bb1d1aa','gauche','gauche','en','vi','/gouʃ/','C2','adjective','vụng về','/audio/vocab/gauche.mp3','[{"source_text":"His gauche remarks embarrassed his date.","target_text":"Những lời vụng về của anh khiến bạn gái ngượng ngùng.","audio_url":"/audio/vocab/gauche-ex.mp3"}]'::jsonb,'published'),
  ('29096d44-bed6-51d7-8698-71a00eddf35f','genomic','genomic','en','vi',NULL,'C2','adjective','thuộc hệ gen','/audio/vocab/genomic.mp3','[{"source_text":"Genomic research promises new cancer treatments.","target_text":"Nghiên cứu hệ gen hứa hẹn phương pháp trị ung thư mới.","audio_url":"/audio/vocab/genomic-ex.mp3"}]'::jsonb,'published'),
  ('581652d5-72f4-5b76-b7b5-5f5cd4b2430b','glitz','glitz','en','vi',NULL,'C2','noun','nét quyến rũ nhất thời, vẻ hào nhoáng giả tạo','/audio/vocab/glitz.mp3','[{"source_text":"She was bored by the glitz of fame.","target_text":"Cô ấy chán ngấy vẻ hào nhoáng của danh vọng.","audio_url":"/audio/vocab/glitz-ex.mp3"}]'::jsonb,'published'),
  ('f8fa1c3e-0b04-5858-9b6d-4758f2840c36','glitzy','glitzy','en','vi',NULL,'C2','adjective','giả tạo, phù phiếm','/audio/vocab/glitzy.mp3','[{"source_text":"They moved into a glitzy apartment downtown.","target_text":"Họ chuyển vào căn hộ hào nhoáng ở trung tâm.","audio_url":"/audio/vocab/glitzy-ex.mp3"}]'::jsonb,'published'),
  ('04aa6555-4fbb-5e7f-89cb-ed4051f30139','graft','graft','en','vi','/grɑ:ft/','C2','noun','cành ghép','/audio/vocab/graft.mp3','[{"source_text":"The graft took well on the old tree.","target_text":"Cành ghép đã bám tốt vào cây cổ thụ.","audio_url":"/audio/vocab/graft-ex.mp3"}]'::jsonb,'published'),
  ('e9a86f81-e157-5013-8f31-0a33f966c9d1','grievance','grievance','en','vi','/''gri:vəns/','C2','noun','lời trách, lời phàn nàn, lời kêu ca','/audio/vocab/grievance.mp3','[{"source_text":"","target_text":"","audio_url":null}]'::jsonb,'published'),
  ('a7c9cd89-a5a9-5f8d-a5c0-a4836b09ea6d','habitation','habitation','en','vi','/,hæbi''teiʃn/','C2','noun','sự ở, sự cư trú','/audio/vocab/habitation.mp3','[{"source_text":"These caves show signs of ancient habitation.","target_text":"Những hang động này có dấu vết cư trú của người xưa.","audio_url":"/audio/vocab/habitation-ex.mp3"}]'::jsonb,'published'),
  ('1764335a-57a8-5bed-ab09-7e88ab34c5bc','haphazard','haphazard','en','vi','/''hæp''hæzəd/','C2','adjective','sự may rủi, sự ngẫu nhiên, sự tình cờ','/audio/vocab/haphazard.mp3','[{"source_text":"The files were stacked in haphazard piles.","target_text":"Các tập hồ sơ chất thành đống bừa bãi.","audio_url":"/audio/vocab/haphazard-ex.mp3"}]'::jsonb,'published'),
  ('21d1b3f1-ff48-573a-95f2-c33d699cf565','haphazardly','haphazardly','en','vi',NULL,'C2','adverb','bừa bãi, lung tung','/audio/vocab/haphazardly.mp3','[{"source_text":"He haphazardly tossed clothes into the suitcase.","target_text":"Anh quăng quần áo vào vali một cách bừa bãi.","audio_url":"/audio/vocab/haphazardly-ex.mp3"}]'::jsonb,'published'),
  ('6466c77c-dd97-53ed-8d30-412adae505bd','headmistress','headmistress','en','vi',NULL,'C2','noun','bà hiệu trưởng','/audio/vocab/headmistress.mp3','[{"source_text":"The headmistress addressed the school on Monday.","target_text":"Bà hiệu trưởng phát biểu trước toàn trường vào thứ Hai.","audio_url":"/audio/vocab/headmistress-ex.mp3"}]'::jsonb,'published'),
  ('be6b9f4d-a187-5d99-b4c6-c98b72ff3569','hindsight','hindsight','en','vi','/''haindsait/','C2','noun','thước ngắm','/audio/vocab/hindsight.mp3','[{"source_text":"In hindsight, we should have saved more.","target_text":"Nhìn lại, lẽ ra chúng tôi nên tiết kiệm nhiều hơn.","audio_url":"/audio/vocab/hindsight-ex.mp3"}]'::jsonb,'published'),
  ('5cef12ad-cca5-597c-8c2f-04e562102d13','hypothesize','hypothesize','en','vi','/hai''pɔθisaiz/','C2','verb','đưa ra một giả thuyết','/audio/vocab/hypothesize.mp3','[{"source_text":"Scientists hypothesize that sleep aids memory.","target_text":"Các nhà khoa học giả thuyết rằng giấc ngủ giúp củng cố trí nhớ.","audio_url":"/audio/vocab/hypothesize-ex.mp3"}]'::jsonb,'published'),
  ('9931a6e3-393c-5c7b-8529-708c1d16c73e','hypothetical','hypothetical','en','vi',NULL,'C2','adjective','Cách viết khác : hypothetic','/audio/vocab/hypothetical.mp3','[{"source_text":"Let us consider a hypothetical situation.","target_text":"Hãy xét một tình huống giả định.","audio_url":"/audio/vocab/hypothetical-ex.mp3"}]'::jsonb,'published'),
  ('92ff481d-a118-5759-ac82-ac175f5e9feb','idle','idle','en','vi','/''aidl/','C2','verb','ngồi rồi, không làm việc gì','/audio/vocab/idle.mp3','[{"source_text":"He is ashamed of being idle.","target_text":"Ông là xấu hổ vì ở không (không làm gì cả).","audio_url":"/audio/vocab/idle-ex.mp3"}]'::jsonb,'published'),
  ('8eb31f23-8647-58f0-a10b-07c25452c918','imposition','imposition','en','vi','/,impə''ziʃn/','C2','noun','sự đánh thuế má','/audio/vocab/imposition.mp3','[{"source_text":"The new tax was an unwelcome imposition.","target_text":"Khoản thuế mới là gánh nặng không mong muốn.","audio_url":"/audio/vocab/imposition-ex.mp3"}]'::jsonb,'published'),
  ('91c1ea18-0441-50c2-a822-08f2ba8ae871','inartistic','inartistic','en','vi','/,inɑ:''tistik/','C2','adjective','không mỹ thuật, thiếu mỹ thuật','/audio/vocab/inartistic.mp3','[{"source_text":"The inartistic concrete blocks spoiled the square.","target_text":"Những khối bê tông thiếu mỹ thuật làm xấu quảng trường.","audio_url":"/audio/vocab/inartistic-ex.mp3"}]'::jsonb,'published'),
  ('40dae500-ad70-5076-9636-c6086b0a2675','indignant','indignant','en','vi','/in''dignent/','C2','adjective','căm phẫn, phẫn nộ, công phẫn','/audio/vocab/indignant.mp3','[{"source_text":"Grace wore an indignant look.","target_text":"Grace tỏ ra bất bình.","audio_url":"/audio/vocab/indignant-ex.mp3"}]'::jsonb,'published'),
  ('5a775825-53c1-5543-89bc-9ad8ff268dae','indignantly','indignantly','en','vi',NULL,'C2','adverb','căm phẫn, phẫn nộ','/audio/vocab/indignantly.mp3','[{"source_text":"She indignantly denied the accusation.","target_text":"Cô phẫn nộ phủ nhận lời buộc tội.","audio_url":"/audio/vocab/indignantly-ex.mp3"}]'::jsonb,'published'),
  ('fe610a4f-0b69-5ea6-b372-0240fd0c7374','individualism','individualism','en','vi','/,indi''vidjuəlizm/','C2','noun','chủ nghĩa cá nhân','/audio/vocab/individualism.mp3','[{"source_text":"American culture often celebrates rugged individualism.","target_text":"Văn hóa Mỹ thường đề cao chủ nghĩa cá nhân.","audio_url":"/audio/vocab/individualism-ex.mp3"}]'::jsonb,'published'),
  ('c71c03a1-d557-5545-b69d-7ff89a9e571f','indulgence','indulgence','en','vi','/in''dʌldʤəns/','C2','noun','sự nuông chiều, sự chiều theo','/audio/vocab/indulgence.mp3','[{"source_text":"A spa day was her only indulgence.","target_text":"Một ngày ở spa là thú vui xa xỉ duy nhất của cô.","audio_url":"/audio/vocab/indulgence-ex.mp3"}]'::jsonb,'published'),
  ('2a2a384a-57a3-5fb3-b9ec-a097ad8a0d7a','indulgently','indulgently','en','vi',NULL,'C2','adverb','khoan dung, bao dung','/audio/vocab/indulgently.mp3','[{"source_text":"The grandfather smiled indulgently at the children.","target_text":"Ông nội mỉm cười bao dung với lũ trẻ.","audio_url":"/audio/vocab/indulgently-ex.mp3"}]'::jsonb,'published'),
  ('f0d66bde-287a-533b-be4e-a6306e018afe','informant','informant','en','vi','/in''fɔ:mənt/','C2','noun','người cung cấp tin tức','/audio/vocab/informant.mp3','[{"source_text":"The informant tipped off the police anonymously.","target_text":"Người cung cấp tin tức báo cho cảnh sát một cách nặc danh.","audio_url":"/audio/vocab/informant-ex.mp3"}]'::jsonb,'published'),
