  ('bb311e71-efec-50f7-8ca8-25827be86cf2','insular','insular','en','vi','/''insjulə/','C2','adjective','hòn đảo','/audio/vocab/insular.mp3','[{"source_text":"His insular views limited his understanding.","target_text":"Quan điểm thiển cận của anh hạn chế sự hiểu biết.","audio_url":"/audio/vocab/insular-ex.mp3"}]'::jsonb,'published'),
  ('0a88b80e-75ae-5cb4-be94-02050b77b2a0','laud','laud','en','vi','/lɔ:d/','C2','verb','lời tán dương, lời ca ngợi, lời khen ngợi','/audio/vocab/laud.mp3','[{"source_text":"Critics lauded her debut performance.","target_text":"Các nhà phê bình ca ngợi màn trình diễn đầu tay của cô.","audio_url":"/audio/vocab/laud-ex.mp3"}]'::jsonb,'published'),
  ('5d68dc62-9b34-5973-9f24-cdfc7781a01b','laudatory','laudatory','en','vi','/''lɔ:dətəri/','C2','adjective','tán dương, ca ngợi, khen','/audio/vocab/laudatory.mp3','[{"source_text":"","target_text":"","audio_url":null}]'::jsonb,'published'),
  ('fba7960c-7106-5f76-848c-a69681f7e3bd','liaise','liaise','en','vi','/li''eiz/','C2','verb','giữ liên lạc','/audio/vocab/liaise.mp3','[{"source_text":"She liaises with suppliers across three countries.","target_text":"Cô giữ liên lạc với các nhà cung cấp ở ba quốc gia.","audio_url":"/audio/vocab/liaise-ex.mp3"}]'::jsonb,'published'),
  ('1bd7e8af-6538-5668-9905-17de4304f314','locomotion','locomotion','en','vi','/,loukə''mouʃn/','C2','noun','sự di động, sự vận động','/audio/vocab/locomotion.mp3','[{"source_text":"Wings gave birds a new mode of locomotion.","target_text":"Đôi cánh mang đến cho loài chim cách di chuyển mới.","audio_url":"/audio/vocab/locomotion-ex.mp3"}]'::jsonb,'published'),
  ('5bfc6990-1c50-54cd-ba55-3fced47ae775','locomotive','locomotive','en','vi','/''loukə,moutiv/','C2','noun','đầu máy','/audio/vocab/locomotive.mp3','[{"source_text":"The locomotive pulled twelve heavy carriages.","target_text":"Đầu máy kéo mười hai toa nặng.","audio_url":"/audio/vocab/locomotive-ex.mp3"}]'::jsonb,'published'),
  ('d2a5a9a6-9dbb-5ad2-ae6e-24f1350ab32f','malleability','malleability','en','vi','/,mæliə''biliti/','C2','noun','tính dễ dát mỏng, tính dễ uốn','/audio/vocab/malleability.mp3','[{"source_text":"The malleability of copper suits electrical wiring.","target_text":"Tính dễ uốn của đồng phù hợp với dây điện.","audio_url":"/audio/vocab/malleability-ex.mp3"}]'::jsonb,'published'),
  ('af0da7ab-a68e-524b-8a49-caad8e398134','malleable','malleable','en','vi','/''mæliəbl/','C2','adjective','dễ dát mỏng, dễ uốn','/audio/vocab/malleable.mp3','[{"source_text":"Young minds are remarkably malleable.","target_text":"Trí óc trẻ nhỏ có thể uốn nắn đáng kinh ngạc.","audio_url":"/audio/vocab/malleable-ex.mp3"}]'::jsonb,'published'),
  ('574dad90-1d86-5913-a608-75f8ffe4064d','marvel','marvel','en','vi','/''mɑ:vəl/','C2','noun','vật kỳ diệu, vật tuyệt diệu, kỳ công','/audio/vocab/marvel.mp3','[{"source_text":"The bridge is a marvel of engineering.","target_text":"Cây cầu là một kỳ công kỹ thuật.","audio_url":"/audio/vocab/marvel-ex.mp3"}]'::jsonb,'published'),
  ('530ea765-d395-5b05-ba50-eb2f2ca4e41f','materialism','materialism','en','vi','/mə''tiəriəlizm/','C2','noun','chủ nghĩa duy vật','/audio/vocab/materialism.mp3','[{"source_text":"He rejected materialism for a simpler life.","target_text":"Anh từ bỏ chủ nghĩa vật chất để sống giản dị.","audio_url":"/audio/vocab/materialism-ex.mp3"}]'::jsonb,'published'),
  ('0ec4ac79-892d-5f0a-836f-b3227a4eff7a','materialistic','materialistic','en','vi','/mə,tiəriə''listik/','C2','adjective','duy vật','/audio/vocab/materialistic.mp3','[{"source_text":"You''re materialistic.","target_text":"Bạn là một người ham vật chất.","audio_url":"/audio/vocab/materialistic-ex.mp3"}]'::jsonb,'published'),
  ('0cf82ce4-54a1-5e78-9987-2a6b964b502e','menial','menial','en','vi','/''mi:njəl/','C2','adjective','người ở, đầy tớ','/audio/vocab/menial.mp3','[{"source_text":"She refused menial jobs after graduation.","target_text":"Cô từ chối những công việc tay chân sau khi tốt nghiệp.","audio_url":"/audio/vocab/menial-ex.mp3"}]'::jsonb,'published'),
  ('450b7097-bf4f-5e33-85c5-6ef446247469','methodological','methodological','en','vi',NULL,'C2','adjective','phương pháp luận','/audio/vocab/methodological.mp3','[{"source_text":"The study followed a strict methodological approach.","target_text":"Nghiên cứu tuân theo phương pháp luận nghiêm ngặt.","audio_url":"/audio/vocab/methodological-ex.mp3"}]'::jsonb,'published'),
  ('a2cf79b5-ce3a-5fcb-ad47-eceb95f44bd6','midwifery','midwifery','en','vi','/midwifery/','C2','noun','khoa sản','/audio/vocab/midwifery.mp3','[{"source_text":"She trained in midwifery before moving abroad.","target_text":"Cô học nghề hộ sinh trước khi ra nước ngoài.","audio_url":"/audio/vocab/midwifery-ex.mp3"}]'::jsonb,'published'),
  ('7ae22c28-0ad7-527f-9a62-c455eb6f6320','mien','mien','en','vi','/mi:n/','C2','noun','dáng điệu, phong cách','/audio/vocab/mien.mp3','[{"source_text":"His stern mien hid a kind heart.","target_text":"Vẻ nghiêm nghị của ông che giấu một trái tim nhân hậu.","audio_url":"/audio/vocab/mien-ex.mp3"}]'::jsonb,'published'),
  ('750d4ea2-e758-5738-a6b6-b1338e6dcfde','minster','minster','en','vi','/minster/','C2','verb','nhà thờ tu viện','/audio/vocab/minster.mp3','[{"source_text":"The ancient minster stood at the town''s center.","target_text":"Nhà thờ tu viện cổ đứng ở trung tâm thị trấn.","audio_url":"/audio/vocab/minster-ex.mp3"}]'::jsonb,'published'),
  ('61861c78-7e53-5d8d-a02b-86df5b31d2f6','modernism','modernism','en','vi','/''mɔdə:nizm/','C2','noun','quan điểm mới, phương pháp mới','/audio/vocab/modernism.mp3','[{"source_text":"Modernism reshaped art in the twentieth century.","target_text":"Chủ nghĩa hiện đại đã định hình lại nghệ thuật thế kỷ 20.","audio_url":"/audio/vocab/modernism-ex.mp3"}]'::jsonb,'published'),
  ('143c29d6-be4c-526d-ba9a-0791d9617e22','monastic','monastic','en','vi','/mə''næstik/','C2','adjective','tu viện','/audio/vocab/monastic.mp3','[{"source_text":"The monks led a quiet monastic life.","target_text":"Các nhà sư sống cuộc đời tu hành thanh tịnh.","audio_url":"/audio/vocab/monastic-ex.mp3"}]'::jsonb,'published'),
  ('b0f74ede-2c1e-5c6b-be19-84a8c25b304c','nostalgia','nostalgia','en','vi','/nɔs''tældʤiə/','C2','noun','nỗi nhớ nhà, lòng nhớ quê hương','/audio/vocab/nostalgia.mp3','[{"source_text":"Old photographs filled her with nostalgia.","target_text":"Những bức ảnh cũ gợi trong cô nỗi nhớ da diết.","audio_url":"/audio/vocab/nostalgia-ex.mp3"}]'::jsonb,'published'),
  ('44a52817-0171-577d-9385-1a8b1a6732f1','nostalgic','nostalgic','en','vi','/nɔs''tældʤik/','C2','adjective','nhớ nhà, nhớ quê hương','/audio/vocab/nostalgic.mp3','[{"source_text":"The song made him feel nostalgic.","target_text":"Bài hát khiến anh cảm thấy hoài niệm.","audio_url":"/audio/vocab/nostalgic-ex.mp3"}]'::jsonb,'published'),
  ('bfbb778c-9cef-5c63-a599-8a679d25b66a','nostalgically','nostalgically','en','vi',NULL,'C2','adverb','lưu luyến, vấn vương','/audio/vocab/nostalgically.mp3','[{"source_text":"She spoke nostalgically of her childhood summers.","target_text":"Cô nhắc về những mùa hè tuổi thơ đầy lưu luyến.","audio_url":"/audio/vocab/nostalgically-ex.mp3"}]'::jsonb,'published'),
  ('9abd4efa-c907-5ab6-afb9-cab5fd6fb26d','notoriety','notoriety','en','vi','/,noutə''raiəti/','C2','noun','trạng thái rõ ràng, trạng thái hiển nhiên, trạng thái ai cũng biết','/audio/vocab/notoriety.mp3','[{"source_text":"The scandal brought him unwelcome notoriety.","target_text":"Vụ bê bối mang đến cho anh sự tai tiếng không mong muốn.","audio_url":"/audio/vocab/notoriety-ex.mp3"}]'::jsonb,'published'),
  ('79a5deb4-7aa7-5b0e-8950-0b2fad2056a4','notoriously','notoriously','en','vi',NULL,'C2','adverb','lừng danh, khét tiếng','/audio/vocab/notoriously.mp3','[{"source_text":"The road is notoriously dangerous at night.","target_text":"Con đường này khét tiếng nguy hiểm vào ban đêm.","audio_url":"/audio/vocab/notoriously-ex.mp3"}]'::jsonb,'published'),
  ('b27c02c5-108e-540e-bd62-e5dd766ad669','oblique','oblique','en','vi','/ə''bli:k/','C2','adjective','xiên, chéo, chếch','/audio/vocab/oblique.mp3','[{"source_text":"He gave an oblique answer to avoid lying.","target_text":"Anh trả lời vòng vo để tránh nói dối.","audio_url":"/audio/vocab/oblique-ex.mp3"}]'::jsonb,'published'),
