  ('17b7bb45-6b43-56b4-934c-f3e2a1333274','ore','ore','en','vi','/ɔ:/','C2','noun','quặng','/audio/vocab/ore.mp3','[{"source_text":"The miners dug deep for iron ore.","target_text":"Thợ mỏ đào sâu để tìm quặng sắt.","audio_url":"/audio/vocab/ore-ex.mp3"}]'::jsonb,'published'),
  ('35b25e5c-979b-5a72-979d-decc0add87f2','ornate','ornate','en','vi','/ɔ:''neit/','C2','adjective','trang trí công phu, trang sức lộng lẫy','/audio/vocab/ornate.mp3','[{"source_text":"The loaf of bread was adorned with ornate tiny squirrels.","target_text":"Ổ bánh mì được trang trí bằng những con sóc nhỏ xíu được làm rất công phu.","audio_url":"/audio/vocab/ornate-ex.mp3"}]'::jsonb,'published'),
  ('83f14968-fbaf-54e7-a82f-742f2381392f','outmoded','outmoded','en','vi','/''aut''moudid/','C2','adjective','không phải mốt, không còn mốt nữa, cổ lỗ sĩ, lỗi thời','/audio/vocab/outmoded.mp3','[{"source_text":"Typewriters now seem quaintly outmoded.","target_text":"Máy đánh chữ giờ trông thật lỗi thời.","audio_url":"/audio/vocab/outmoded-ex.mp3"}]'::jsonb,'published'),
  ('9c15f090-0158-54ff-b359-ce7d629fe5e4','outpatient','outpatient','en','vi','/''aut,peiʃənt/','C2','noun','người bệnh ở ngoài, người bệnh ngoại trú','/audio/vocab/outpatient.mp3','[{"source_text":"The clinic treats outpatients every weekday.","target_text":"Phòng khám tiếp nhận bệnh nhân ngoại trú mỗi ngày trong tuần.","audio_url":"/audio/vocab/outpatient-ex.mp3"}]'::jsonb,'published'),
  ('42283298-2656-5d40-a309-b3362993fe4a','overlay','overlay','en','vi','/''ouvəlei/','C2','verb','vật phủ','/audio/vocab/overlay.mp3','[{"source_text":"New paint overlaid the old mural.","target_text":"Lớp sơn mới phủ lên bức bích họa cũ.","audio_url":"/audio/vocab/overlay-ex.mp3"}]'::jsonb,'published'),
  ('a2fd7794-57dd-5611-a5d8-8cfcca6fe7c4','parable','parable','en','vi','/''pærəbl/','C2','noun','truyện ngụ ngôn','/audio/vocab/parable.mp3','[{"source_text":"The teacher explained kindness through a simple parable.","target_text":"Thầy giáo giảng về lòng tốt qua một câu chuyện ngụ ngôn đơn giản.","audio_url":"/audio/vocab/parable-ex.mp3"}]'::jsonb,'published'),
  ('a8fa194e-0b77-5cad-a183-35733f190884','parasitic','parasitic','en','vi','/,pærə''sitik/','C2','adjective','ăn bám, ký sinh','/audio/vocab/parasitic.mp3','[{"source_text":"The parasitic plant drains nutrients from trees.","target_text":"Cây ký sinh hút chất dinh dưỡng từ cây cối.","audio_url":"/audio/vocab/parasitic-ex.mp3"}]'::jsonb,'published'),
  ('32fcbb17-632b-5c33-995a-9855611dbcf8','pervasive','pervasive','en','vi','/pə:''veisiv/','C2','adjective','toả khắp','/audio/vocab/pervasive.mp3','[{"source_text":"The smell of coffee was pervasive in the cafe.","target_text":"Mùi cà phê lan tỏa khắp quán.","audio_url":"/audio/vocab/pervasive-ex.mp3"}]'::jsonb,'published'),
  ('fad1ecbe-8ece-5316-bc26-50362b3d9827','pervasiveness','pervasiveness','en','vi',NULL,'C2','noun','sự lan tỏa, tính thâm nhập rộng khắp','/audio/vocab/pervasiveness.mp3','[{"source_text":"The pervasiveness of smartphones reshaped daily life.","target_text":"Sự phổ biến khắp nơi của điện thoại đã thay đổi đời sống hằng ngày.","audio_url":"/audio/vocab/pervasiveness-ex.mp3"}]'::jsonb,'published'),
  ('296b1c36-89af-5a85-a38a-8b7e3627b74b','physiological','physiological','en','vi','/,fiziə''lɔdʤik/','C2','adjective','sinh lý học','/audio/vocab/physiological.mp3','[{"source_text":"Stress triggers a physiological response in the body.","target_text":"Căng thẳng gây ra phản ứng sinh lý trong cơ thể.","audio_url":"/audio/vocab/physiological-ex.mp3"}]'::jsonb,'published'),
  ('afaa4fc4-ef8b-501b-9375-829a86221134','physiologically','physiologically','en','vi',NULL,'C2','adverb','về mặt sinh lý học','/audio/vocab/physiologically.mp3','[{"source_text":"The twins are physiologically identical but emotionally different.","target_text":"Hai chị em sinh đôi giống nhau về sinh lý nhưng khác về cảm xúc.","audio_url":"/audio/vocab/physiologically-ex.mp3"}]'::jsonb,'published'),
  ('02441371-0d27-54a3-b493-f9fbef14a8ea','pluck','pluck','en','vi','/plʌk/','C2','noun','sự giật, sự kéo, cái giật, cái kéo','/audio/vocab/pluck.mp3','[{"source_text":"It took pluck to challenge the champion.","target_text":"Cần rất nhiều dũng khí để thách đấu nhà vô địch.","audio_url":"/audio/vocab/pluck-ex.mp3"}]'::jsonb,'published'),
  ('1be74a9b-709e-5b0e-bebb-7f2d3dbe5507','plum','plum','en','vi','/plʌm/','C2','adjective','quả mận','/audio/vocab/plum.mp3','[{"source_text":"She landed a plum position at the bank.","target_text":"Cô giành được một vị trí đáng mơ ước ở ngân hàng.","audio_url":"/audio/vocab/plum-ex.mp3"}]'::jsonb,'published'),
  ('a54ae3d8-b3b4-5476-a7bf-2675ededd7db','plumage','plumage','en','vi','/''plu:midʤ/','C2','noun','bộ lông','/audio/vocab/plumage.mp3','[{"source_text":"The peacock displayed its brilliant plumage.","target_text":"Con công xòe bộ lông rực rỡ.","audio_url":"/audio/vocab/plumage-ex.mp3"}]'::jsonb,'published'),
  ('73ca8523-7c2d-5fd2-b759-f8f01546d841','poise','poise','en','vi','/pɔiz/','C2','verb','thế thăng bằng, thế cân bằng','/audio/vocab/poise.mp3','[{"source_text":"The cat poised itself to pounce.","target_text":"Con mèo rình thế chuẩn bị vồ mồi.","audio_url":"/audio/vocab/poise-ex.mp3"}]'::jsonb,'published'),
  ('c5692705-71ab-59b3-afb1-eca97ebe2f09','portraiture','portraiture','en','vi','/''pɔ:tritʃə/','C2','noun','cách vẽ chân dung','/audio/vocab/portraiture.mp3','[{"source_text":"The exhibition celebrated Victorian portraiture.","target_text":"Triển lãm tôn vinh nghệ thuật chân dung thời Victoria.","audio_url":"/audio/vocab/portraiture-ex.mp3"}]'::jsonb,'published'),
  ('c55d236b-b798-5333-b06d-df548f008c2d','posit','posit','en','vi','/''pɔzit/','C2','verb','thừa nhận, cho là đúng','/audio/vocab/posit.mp3','[{"source_text":"The theory posits a link between diet and mood.","target_text":"Lý thuyết này cho rằng chế độ ăn liên quan đến tâm trạng.","audio_url":"/audio/vocab/posit-ex.mp3"}]'::jsonb,'published'),
  ('46fed3c5-4002-5ad8-8624-000486cf17b6','postural','postural','en','vi',NULL,'C2','adjective','thuộc tư thế','/audio/vocab/postural.mp3','[{"source_text":"Yoga improves postural alignment and balance.","target_text":"Yoga cải thiện tư thế và khả năng giữ thăng bằng.","audio_url":"/audio/vocab/postural-ex.mp3"}]'::jsonb,'published'),
  ('7af3c624-53af-5aca-ae4b-f40476b5abe7','posture','posture','en','vi','/''pɔstʃə/','C2','verb','tư thế','/audio/vocab/posture.mp3','[{"source_text":"He postured as a concerned citizen.","target_text":"Anh ta làm ra vẻ là một công dân quan tâm.","audio_url":"/audio/vocab/posture-ex.mp3"}]'::jsonb,'published'),
  ('9aa9fc9e-3337-50a5-b3a7-48101f9493f6','posturing','posturing','en','vi',NULL,'C2','noun','việc làm dáng, làm điệu bộ','/audio/vocab/posturing.mp3','[{"source_text":"Their posturing delayed any real agreement.","target_text":"Thói làm màu của họ làm chậm mọi thỏa thuận thực sự.","audio_url":"/audio/vocab/posturing-ex.mp3"}]'::jsonb,'published'),
  ('0a08e8b5-dccb-515b-acab-29fdc9020daa','predilection','predilection','en','vi','/,pri:di''lekʃn/','C2','noun','+ for) lòng ưa riêng','/audio/vocab/predilection.mp3','[{"source_text":"She has a predilection for spicy food.","target_text":"Cô đặc biệt thích đồ ăn cay.","audio_url":"/audio/vocab/predilection-ex.mp3"}]'::jsonb,'published'),
  ('7595deff-a54a-519a-b1f2-c95c6dcb4edb','presuppose','presuppose','en','vi','/,pri:sə''pouz/','C2','verb','giả định trước, phỏng định trước, đoán chừng trước','/audio/vocab/presuppose.mp3','[{"source_text":"Your plan presupposes unlimited funding.","target_text":"Kế hoạch của anh mặc định là có nguồn vốn vô hạn.","audio_url":"/audio/vocab/presuppose-ex.mp3"}]'::jsonb,'published'),
  ('0eb5d46d-ddf3-5a17-b1c3-fa90cb1bc0ca','presupposition','presupposition','en','vi','/,pri:sʌpə''ziʃn/','C2','noun','sự giả định trước, sự phỏng định trước, sự đoán chừng trước','/audio/vocab/presupposition.mp3','[{"source_text":"The argument rests on a false presupposition.","target_text":"Lập luận dựa trên một tiền đề sai.","audio_url":"/audio/vocab/presupposition-ex.mp3"}]'::jsonb,'published'),
  ('f6c97a6a-64ee-54b0-b3f4-510eac228b64','primeval','primeval','en','vi',NULL,'C2','adjective','nguyên thủy','/audio/vocab/primeval.mp3','[{"source_text":"A primeval forest covered the valley.","target_text":"Rừng nguyên sinh bao phủ thung lũng.","audio_url":"/audio/vocab/primeval-ex.mp3"}]'::jsonb,'published'),
  ('8fd7b65c-c2be-5926-9ae5-fd2b6a7225fa','proliferation','proliferation','en','vi','/proliferation/','C2','noun','sự nảy nở','/audio/vocab/proliferation.mp3','[{"source_text":"The proliferation of cafes changed the street.","target_text":"Sự mọc lên như nấm của các quán cà phê đã thay đổi con phố.","audio_url":"/audio/vocab/proliferation-ex.mp3"}]'::jsonb,'published'),
  ('cf25ea9b-17ae-5df0-94a1-db34b2bfbfc5','promenade','promenade','en','vi','/promenade/','C2','noun','cuộc đi dạo','/audio/vocab/promenade.mp3','[{"source_text":"Couples strolled along the seaside promenade.","target_text":"Các cặp đôi dạo bước trên đường đi bộ ven biển.","audio_url":"/audio/vocab/promenade-ex.mp3"}]'::jsonb,'published'),
