  ('9fc177d5-41b0-5ecd-ac61-fab6e3d5d217','proportionally','proportionally','en','vi',NULL,'C2','adverb','cân xứng, cân đối','/audio/vocab/proportionally.mp3','[{"source_text":"Taxes rise proportionally with income.","target_text":"Thuế tăng tương xứng với thu nhập.","audio_url":"/audio/vocab/proportionally-ex.mp3"}]'::jsonb,'published'),
  ('174423c9-2c9c-5be7-a0a3-99b989cc7a82','prostrate','prostrate','en','vi','/prostrate/','C2','verb','nằm úp sấp, nằm sóng soài','/audio/vocab/prostrate.mp3','[{"source_text":"The worshippers prostrated themselves before the altar.","target_text":"Các tín đồ phủ phục trước bàn thờ.","audio_url":"/audio/vocab/prostrate-ex.mp3"}]'::jsonb,'published'),
  ('6fc58b84-6fa2-5d3f-a8dd-c15bb4c605bd','provocation','provocation','en','vi','/provocation/','C2','noun','sự khích, sự xúi giục, sự khích động','/audio/vocab/provocation.mp3','[{"source_text":"He ignored their provocation and walked away.","target_text":"Anh phớt lờ sự khiêu khích của họ và bỏ đi.","audio_url":"/audio/vocab/provocation-ex.mp3"}]'::jsonb,'published'),
