  ('fd851c39-c225-5104-867a-790c7cd54113','timidity','timidity','en','vi','/ti''miditi/','C2','noun','tính rụt rè nhút nhát, tính bẽn lẽn e lệ','/audio/vocab/timidity.mp3','[{"source_text":"Timidity kept her from raising her hand.","target_text":"Tính nhút nhát khiến cô không dám giơ tay.","audio_url":"/audio/vocab/timidity-ex.mp3"}]'::jsonb,'published'),
  ('c58e1e23-eec6-5df4-90c7-f4a9ebd08db3','transmitter','transmitter','en','vi','/trænz''mitə/','C2','noun','người truyền','/audio/vocab/transmitter.mp3','[{"source_text":"The transmitter sent signals across the valley.","target_text":"Máy phát truyền tín hiệu khắp thung lũng.","audio_url":"/audio/vocab/transmitter-ex.mp3"}]'::jsonb,'published'),
  ('016a9145-749e-5663-a825-dd58c21fd22d','unencumbered','unencumbered','en','vi','/''ʌnin''kʌmbəd/','C2','adjective','không bị làm lúng túng, không bị làm trở ngại, không bị làm vướng víu','/audio/vocab/unencumbered.mp3','[{"source_text":"Unencumbered by debt, they traveled freely.","target_text":"Không vướng nợ nần, họ đi du lịch thoải mái.","audio_url":"/audio/vocab/unencumbered-ex.mp3"}]'::jsonb,'published'),
  ('da7a2cb6-a4fa-5999-820a-9e65efbc8f75','unequivocal','unequivocal','en','vi','/''ʌni''kwivəkəl/','C2','adjective','không thể giải thích hai cách, không thể lập lờ nước đôi, rõ rệt','/audio/vocab/unequivocal.mp3','[{"source_text":"","target_text":"","audio_url":null}]'::jsonb,'published'),
  ('f417f1f8-61fd-5b6b-ad90-362f3cbf0870','unequivocally','unequivocally','en','vi',NULL,'C2','adverb','một cách rõ ràng, dứt khoát','/audio/vocab/unequivocally.mp3','[{"source_text":"She unequivocally rejected the offer.","target_text":"Cô thẳng thừng từ chối lời đề nghị.","audio_url":"/audio/vocab/unequivocally-ex.mp3"}]'::jsonb,'published'),
